      "path": "dsh/index.js",
      "content": "// dsh-alive: zero-token online status for the DeepSeek Harness web UI.\n// Exposes GET /dsh-alive/ping — a process-local endpoint that answers\n// immediately without any LLM call, so the browser can poll it for free.\nexport const name = 'dsh-alive'\nexport const inject = []\n\nexport function apply(ctx, config = {}) {\n  if (typeof ctx.inject === 'function') {\n    ctx.inject(['webServer'], (scope) => {\n      scope.webServer.register({\n        kind: 'exact',\n        path: '/dsh-alive/ping',\n        handler: async (req, res) => {\n          res.writeHead(200, {\n            'Content-Type': 'application/json',\n            'Cache-Control': 'no-store',\n          })\n          res.end(JSON.stringify({ ok: true, ts: Date.now() }))\n        },\n      })\n    })\n  }\n}\n"
    },
    {
      "path": "client/client.js",
      "content": "// dsh-alive web client: an always-visible online indicator in the\n// conversation header. Polls the process-local /dsh-alive/ping endpoint\n// every 15s — no LLM, no tokens.\nwindow.__ModuleLoader__.load({ id: 'dsh-alive', factory: (require) => {\n  var module = { exports: {} }\n  var exports = module.exports\n  Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })\n  const react = require('react')\n\n  const NS = 'dsh-alive'\n  const name = 'dsh-alive'\n  const inject = ['slots']\n  const PING_INTERVAL = 15000\n\n  function OnlineDot() {\n    const [status, setStatus] = react.useState('checking')\n    react.useEffect(() => {\n      let alive = true\n      const tick = async () => {\n        try {\n          const r = await fetch('/dsh-alive/ping', { cache: 'no-store' })\n          if (alive) setStatus(r.ok ? 'online' : 'offline')\n        } catch (e) {\n          if (alive) setStatus('offline')\n        }\n      }\n      tick()\n      const timer = setInterval(tick, PING_INTERVAL)\n      return () => { alive = false; clearInterval(timer) }\n    }, [])\n\n    const st = {\n      wrap: { display: 'inline-flex', alignItems: 'center', gap: '5px', fontSize: '12px', padding: '2px 10px', borderRadius: '10px', background: 'rgba(128,128,128,0.14)', cursor: 'default' },\n      dot: { width: '8px', height: '8px', borderRadius: '50%', display: 'inline-block' },\n      online: { background: '#22c55e', boxShadow: '0 0 6px #22c55e88' },\n      offline: { background: '#ef4444', boxShadow: '0 0 6px #ef444488' },\n      checking: { background: '#f59e0b' },\n    }\n    const map = { online: '在线', offline: '离线', checking: '检测中…' }\n    return react.createElement('span', { style: st.wrap, title: 'DeepSeek 服务状态（每 15 秒自动检测，不消耗 token）' },\n      react.createElement('span', { style: { ...st.dot, ...st[status] } }),\n      ' ' + (map[status] || ''),\n    )\n  }\n\n  function apply(ctx) {\n    ctx.slots.inject('conversation.session.header.utilities', () => ctx.slots.register({\n      name: 'conversation.session.header.utilities',\n      id: 'dsh-alive',\n      order: 999,\n      label: () => '在线状态',\n      locale: NS,\n    }, OnlineDot))\n  }\n\n  return { name, inject, apply }\n}})\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# dsh-alive: mount the zero-token online status indicator.\n- insert:\n    - id: dsh-alive\n      name: 'dsh-alive'\n"
    }
  ],
